def transform(grid):
    """Add two alternating nested rectangular outlines inside a 5 frame."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    pts = [(r, c) for r in range(h) for c in range(w) if out[r][c] == 5]
    if not pts:
        return out
    top = min(r for r, c in pts)
    bottom = max(r for r, c in pts)
    left = min(c for r, c in pts)
    right = max(c for r, c in pts)
    # Add alternating concentric rectangular rings until the middle is at
    # most 3x3. The final 2x2 center in an even-sized case is filled as a block.
    t, b, l, rgt = top + 1, bottom - 1, left + 1, right - 1
    color = 2
    while t <= b and l <= rgt:
        height, width = b - t + 1, rgt - l + 1
        if height <= 2 or width <= 2:
            for rr in range(t, b + 1):
                for cc in range(l, rgt + 1):
                    out[rr][cc] = color
            break
        if height <= 3 and width <= 3:
            break
        for rr in range(t, b + 1):
            for cc in range(l, rgt + 1):
                if rr in (t, b) or cc in (l, rgt):
                    out[rr][cc] = color
        t, b, l, rgt = t + 1, b - 1, l + 1, rgt - 1
        color = 7 - color  # alternate 2 and 5
    return out
